import { MeshBasicNodeMaterial, MeshStandardNodeMaterial } from 'three/webgpu';
import { uv, mix, color, vec2, fract, sin, dot, float } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry, BoxGeometry, DirectionalLight } = ctx.THREE;

  const root = new Group();
  root.name = 'kinetic-hero-headline';

  const spec = config.intent?.visualSpec ?? {};
  const palette = spec.colors ?? config.colors ?? {};
  const BG0 = (palette.gradientStops && palette.gradientStops[0]?.hex) || palette.background || '#0b0b10';
  const BG1 = (palette.gradientStops && palette.gradientStops[1]?.hex) || '#13131a';
  const PAPER = palette.paper || '#e8ecf2';
  const INK = palette.ink || '#16161d';
  const ACCENT = palette.accent || '#ff2a38';

  const disposables = [];
  const timelines = [];
  const primHandles = [];

  // ---------- Backdrop: engineered vertical gradient + mono grain ----------
  const backdropGeo = new PlaneGeometry(7, 5.5);
  const backdropMat = new MeshBasicNodeMaterial();
  const grain = fract(
    sin(dot(uv().mul(float(917.0)), vec2(12.9898, 78.233))).mul(float(43758.5453))
  ).sub(float(0.5)).mul(float(0.015));
  backdropMat.colorNode = mix(color(BG0), color(BG1), uv().y).add(grain);
  const backdrop = new Mesh(backdropGeo, backdropMat);
  backdrop.position.set(0, 0, -1.5);
  root.add(backdrop);
  disposables.push(backdropGeo, backdropMat);

  // ---------- Text content (verbatim from spec) ----------
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const byRole = (role) => items.find((i) => i.role === role);
  const heroItem = byRole('hero') || { text: 'TIME, MACHINED.', typography: { fontSize: 124 } };
  const subItem = byRole('subhead') || { text: 'Every calibre begins as a solid billet.', typography: { fontSize: 40 } };
  const capItem = byRole('caption') || { text: 'NOVA ATELIER / CALIBRE PROGRAM', typography: { fontSize: 18 } };

  const collectMaterials = (obj) => {
    const mats = [];
    obj.traverse((c) => {
      if (c.material) {
        const arr = Array.isArray(c.material) ? c.material : [c.material];
        for (const m of arr) mats.push(m);
      }
    });
    return mats;
  };
  const prepFade = (obj) => {
    const mats = collectMaterials(obj);
    for (const m of mats) { m.transparent = true; m.opacity = 0; }
    return mats;
  };

  // ---------- Hero: dimensional type stack (front / mid / back) ----------
  const heroGroup = new Group();
  heroGroup.position.set(0, 0.4, 0);
  root.add(heroGroup);

  const heroSize = heroItem.typography?.fontSize ?? 124;
  const heroLS = -0.01 * heroSize;

  const heroBack = ctx.fontAtlas.createText(heroItem.text, {
    fontSize: heroSize, color: INK, align: 'center', letterSpacingPx: heroLS
  });
  heroBack.position.set(0.02, -0.02, -0.12);
  heroGroup.add(heroBack);

  const heroMid = ctx.fontAtlas.createText(heroItem.text, {
    fontSize: heroSize, color: '#565b66', align: 'center', letterSpacingPx: heroLS
  });
  heroMid.position.set(0.01, -0.01, 0.0);
  heroGroup.add(heroMid);

  const heroFront = ctx.fontAtlas.createText(heroItem.text, {
    fontSize: heroSize, color: PAPER, align: 'center', letterSpacingPx: heroLS
  });
  heroFront.position.set(0, 0, 0.12);
  heroGroup.add(heroFront);

  // ---------- Accent underline rule (left-anchored scaleX) ----------
  const underlinePivot = new Group();
  underlinePivot.position.set(-1.3, -0.05, 0.05);
  const underlineGeo = new BoxGeometry(2.6, 0.045, 0.02);
  const underlineMat = new MeshStandardNodeMaterial({
    color: ACCENT, roughness: 0.5, metalness: 0.2,
    emissive: ACCENT, emissiveIntensity: 1.2
  });
  const underline = new Mesh(underlineGeo, underlineMat);
  underline.position.set(1.3, 0, 0);
  underlinePivot.add(underline);
  underlinePivot.scale.x = 0.0001;
  root.add(underlinePivot);
  disposables.push(underlineGeo, underlineMat);

  // ---------- Subhead ----------
  const subhead = ctx.fontAtlas.createText(subItem.text, {
    fontSize: subItem.typography?.fontSize ?? 40,
    color: PAPER, align: 'center',
    letterSpacingPx: 0.02 * (subItem.typography?.fontSize ?? 40)
  });
  subhead.position.set(0, -0.85, 0.05);
  root.add(subhead);

  // ---------- Caption kicker ----------
  const capSize = capItem.typography?.fontSize ?? 18;
  const caption = ctx.fontAtlas.createText(String(capItem.text).toUpperCase(), {
    fontSize: capSize, color: PAPER, align: 'center',
    letterSpacingPx: 0.12 * capSize
  });
  caption.position.set(0, 1.15, 0.05);
  root.add(caption);

  // ---------- Foreground accent tick (third depth plane) ----------
  const tickGeo = new BoxGeometry(0.045, 0.25, 0.02);
  const tickMat = new MeshStandardNodeMaterial({
    color: ACCENT, roughness: 0.55, metalness: 0.2,
    emissive: ACCENT, emissiveIntensity: 0.8
  });
  const tick = new Mesh(tickGeo, tickMat);
  tick.position.set(-3.0, 1.15, 0.6);
  root.add(tick);
  disposables.push(tickGeo, tickMat);

  // ---------- Node-local rim light (accent hue, from behind) ----------
  const rim = new DirectionalLight(ACCENT, 0.8);
  rim.position.set(-2.5, 1.2, -2.0);
  root.add(rim);

  // ---------- Cinematic primitives from config ----------
  for (const prim of config.cinematicPrimitives ?? []) {
    const fn = ctx.primitives[prim.name];
    if (fn) primHandles.push(fn(heroGroup, prim.params ?? {}));
  }

  // ---------- Entrance choreography ----------
  const heroMats = collectMaterials(heroGroup);
  for (const m of heroMats) m.transparent = true;
  const subMats = prepFade(subhead);
  const capMats = prepFade(caption);
  tickMat.transparent = true;
  tickMat.opacity = 0;

  // Last glyph lands at ~ (glyphCount-1)*60ms + 700ms
  const glyphCount = String(heroItem.text).length;
  const lastLand = ((glyphCount - 1) * 0.06) + 0.7;

  const tl = gsap.timeline();
  timelines.push(tl);

  // Caption fades up first
  tl.fromTo(caption.position, { y: 1.35 }, { y: 1.15, duration: 0.5, ease: 'power1.out' }, 0.1);
  if (capMats.length) tl.to(capMats, { opacity: 1, duration: 0.5, ease: 'power1.out' }, 0.1);
  tl.to(tickMat, { opacity: 1, duration: 0.5, ease: 'power1.out' }, 0.2);

  // Weighted settle after final glyph lands
  tl.fromTo(heroGroup.scale,
    { x: 1.04, y: 1.04, z: 1.04 },
    { x: 1, y: 1, z: 1, duration: 0.9, ease: 'power4.out' },
    lastLand
  );

  // Underline rule 120ms after last glyph, left-anchored
  tl.to(underlinePivot.scale, { x: 1, duration: 0.5, ease: 'power1.out' }, lastLand + 0.12);

  // Subhead fade-up
  tl.to(subhead.position, { y: -0.65, duration: 0.5, ease: 'power1.out' }, lastLand + 0.25);
  if (subMats.length) tl.to(subMats, { opacity: 1, duration: 0.5, ease: 'power1.out' }, lastLand + 0.25);

  // ---------- Handlers + cleanup ----------
  root.userData.handlers = {};
  root.userData.cleanup = () => {
    for (const t of timelines) t.kill();
    for (const h of primHandles) { if (h && typeof h.cleanup === 'function') h.cleanup(); }
    for (const d of disposables) { if (d && typeof d.dispose === 'function') d.dispose(); }
    root.traverse((c) => {
      if (c.geometry && typeof c.geometry.dispose === 'function') c.geometry.dispose();
      if (c.material) {
        const arr = Array.isArray(c.material) ? c.material : [c.material];
        for (const m of arr) { if (typeof m.dispose === 'function') m.dispose(); }
      }
    });
  };

  return root;
}
